-- Operational reporting queries used by the admin dashboard.
create or replace function seller_revenue(p_seller uuid,p_from timestamptz,p_to timestamptz) returns table(day date,gross numeric,orders bigint) language sql stable as $$ select created_at::date,sum(total),count(*) from orders where seller_id=p_seller and status='completed' and created_at>=p_from and created_at<p_to group by 1 order by 1 $$;
create or replace function category_conversion(p_category uuid,p_from timestamptz,p_to timestamptz) returns table(views bigint,orders bigint,conversion numeric) language sql stable as $$ with v as(select count(*) n from audit_log where action='gig_view' and metadata->>'categoryId'=p_category::text and created_at between p_from and p_to),o as(select count(*) n from orders join gigs on gigs.id=orders.gig_id where gigs.category_id=p_category and orders.created_at between p_from and p_to) select v.n,o.n,case when v.n=0 then 0 else round(o.n::numeric/v.n,4) end from v,o $$;
